CREATE POLICY "Avatar owners can view" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='avatars' AND split_part(name,'.',1)=auth.uid()::text);
CREATE POLICY "Avatar owners can upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='avatars' AND split_part(name,'.',1)=auth.uid()::text);
CREATE POLICY "Avatar owners can update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id='avatars' AND split_part(name,'.',1)=auth.uid()::text) WITH CHECK (bucket_id='avatars' AND split_part(name,'.',1)=auth.uid()::text);
CREATE POLICY "Avatar owners can delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='avatars' AND split_part(name,'.',1)=auth.uid()::text);